CREATE OR REPLACE FUNCTION public.icash_dealmachine_saved_owner_result_valid(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare field text;person jsonb;ph jsonb;used integer;people integer;deduplicated integer;found_count integer;shared_count integer:=0;
begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>262144 or jsonb_typeof(p->'contacts') is distinct from 'array'
  or jsonb_typeof(p->'requestedPersonIds') is distinct from 'array' or jsonb_typeof(p->'providerCredits') is distinct from 'object'
  or p->'outreachAuthorized' is distinct from 'false'::jsonb then return false;end if;
 found_count:=jsonb_array_length(p->'contacts');
 if found_count>25 or jsonb_array_length(p->'requestedPersonIds') not between 1 and 25
  or exists(select 1 from jsonb_array_elements(p->'requestedPersonIds') x where jsonb_typeof(x) is distinct from 'string' or (x#>>'{}') !~ '^per_[A-Za-z0-9]{1,100}$')
  or (select count(distinct value) from jsonb_array_elements(p->'requestedPersonIds'))<>jsonb_array_length(p->'requestedPersonIds') then return false;end if;
 foreach field in array array['used','people','properties','deduplicated'] loop
  if jsonb_typeof(p->'providerCredits'->field) is distinct from 'number' or (p->'providerCredits'->>field) !~ '^[0-9]{1,3}$' then return false;end if;
 end loop;
 used:=(p->'providerCredits'->>'used')::integer;people:=(p->'providerCredits'->>'people')::integer;deduplicated:=(p->'providerCredits'->>'deduplicated')::integer;
 if p ? 'allocation' then
  if jsonb_typeof(p->'allocation') is distinct from 'object'
   or p->'allocation'->>'method' is distinct from 'unique-person-order-v1'
   or coalesce(p->'allocation'->>'batchId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or jsonb_typeof(p->'allocation'->'sharedContacts') is distinct from 'number'
   or coalesce(p->'allocation'->>'sharedContacts','') !~ '^[0-9]{1,2}$' then return false;end if;
  shared_count:=(p->'allocation'->>'sharedContacts')::integer;
  if shared_count>found_count then return false;end if;
 end if;
 if people+shared_count<>found_count or (p->'providerCredits'->>'properties')::integer<>0 or used+deduplicated<>people
  or p->'creditsUsed' is distinct from p->'providerCredits'->'used' or p->'peopleCredits' is distinct from p->'providerCredits'->'people'
  or (select count(distinct value->>'personId') from jsonb_array_elements(p->'contacts'))<>found_count then return false;end if;
 for person in select value from jsonb_array_elements(p->'contacts') loop
  if jsonb_typeof(person) is distinct from 'object' or not (p->'requestedPersonIds' ? coalesce(person->>'personId',''))
   or jsonb_typeof(person->'likelyOwner') is distinct from 'boolean'
   or person->'ownershipVerified' is distinct from 'false'::jsonb or person->'outreachAuthorized' is distinct from 'false'::jsonb
   or jsonb_typeof(person->'phones') is distinct from 'array' then return false;end if;
  if jsonb_array_length(person->'phones')>20 then return false;end if;
  for ph in select value from jsonb_array_elements(person->'phones') loop
   if jsonb_typeof(ph) is distinct from 'object' or ph->>'permission' is distinct from 'unverified'
    or not (ph ? 'number') or (jsonb_typeof(ph->'number') not in ('string','null')) then return false;end if;
  end loop;
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_owner_batch(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;r public.icash_operation_rates;item jsonb;sid uuid;op text;preview jsonb;person text;
begin
 if p_batch is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5 or octet_length(p_preview::text)>2097152 then return false;end if;
 if not exists(select 1 from jsonb_array_elements(p_items) v where v->>'screeningId'=p_primary::text)
 or (select count(distinct v->>'screeningId') from jsonb_array_elements(p_items) v)<>jsonb_array_length(p_items) then return false;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found or not public.icash_membership_work_allowed(p_account) then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if coalesce(c.research_version,0) not in (1,2) or row(c.contact_rate_id,c.contact_credit_cap,c.property_credit_micros,c.data_rights_until) is distinct from row((p_config->>'rateId')::uuid,(p_config->>'creditCap')::integer,(p_config->>'unitCostMicros')::bigint,(p_config->>'rightsUntil')::timestamptz) then return false;end if;
 select * into r from public.icash_operation_rates where id=c.contact_rate_id;
 if exists(select 1 from icash_research_private.owner_batches where id=p_batch) or (p_preview->'credits' @> '{"used":0,"people":0,"properties":0,"deduplicated":0}'::jsonb) is distinct from true then return false;end if;
 if not public.icash_take_dealmachine_request('owner_lookup',p_account,'owner-batch:'||p_batch,p_batch) then return false;end if;
 for item in select value from jsonb_array_elements(p_items) loop
  sid:=(item->>'screeningId')::uuid;op:='owners:'||p_account||':'||sid;
  if jsonb_typeof(item->'ids') is distinct from 'array' or jsonb_array_length(item->'ids') not between 1 and c.contact_credit_cap then raise exception 'Owner batch audience invalid';end if;
  if sid<>p_primary and exists(select 1 from public.icash_automation_tickets where screening_id=sid) then raise exception 'Owner batch sibling already ticketed';end if;
  if exists(select 1 from public.icash_operation_spend where operation_key=op) then raise exception 'Owner batch operation already exists';end if;
  if exists(select 1 from public.icash_owner_contacts oc join public.icash_screening_jobs prior on prior.id=oc.screening_id where oc.account_id=p_account and prior.snapshot->>'propertyId'=item->'snapshot'->>'propertyId' and oc.created_at>now()-interval '30 days') then raise exception 'Owner batch property already enriched';end if;
  select value into strict preview from jsonb_array_elements(p_preview->'data') where value->>'dm_property_id'=item->'snapshot'->>'propertyId' and value->'found'='true'::jsonb;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   if person !~ '^per_[a-zA-Z0-9]{1,100}$' or not exists(select 1 from jsonb_array_elements(preview->'contacts') p where p->>'dm_person_id'=person and p->'is_likely_renter' is distinct from 'true'::jsonb and (p->'is_likely_owner'='true'::jsonb or (p->>'is_likely_owner' is null and p->>'contact_type'='owner'))) then raise exception 'Owner batch preview mismatch';end if;
  end loop;
  perform public.icash_reserve_operation(p_account,op,c.contact_rate_id,c.data_rights_until,null,false);
  if not public.icash_claim_owner_enrichment(p_account,sid,op,item->'snapshot',c.contact_rate_id,c.contact_credit_cap,c.property_credit_micros,(r.costs_micros->>'dealmachine')::bigint,c.data_rights_until) then raise exception 'Owner batch admission held';end if;
 end loop;
 insert into icash_research_private.owner_batches(id,account_id,primary_screening,items,preview_receipt) values(p_batch,p_account,p_primary,p_items,p_preview);
 insert into icash_research_private.owner_batch_items select (v->>'screeningId')::uuid,p_batch,'owners:'||p_account||':'||(v->>'screeningId') from jsonb_array_elements(p_items) v;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_dealmachine_owner_source_started_at(p_account uuid, p_screening uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oc public.icash_owner_contacts;b icash_research_private.owner_batches;item jsonb;result jsonb;
begin
 select * into oc from public.icash_owner_contacts where account_id=p_account and screening_id=p_screening;
 if not found then return null;end if;
 if not (oc.result ? 'allocation') then return public.icash_dealmachine_request_started_at(oc.result);end if;
 if jsonb_typeof(oc.result->'allocation') is distinct from 'object'
  or oc.result->'allocation'->>'method' is distinct from 'unique-person-order-v1' then return null;end if;
 select batch.* into b from icash_research_private.owner_batch_items binding
 join icash_research_private.owner_batches batch on batch.id=binding.batch_id
 where binding.screening_id=p_screening and binding.operation_key=oc.operation_key
  and batch.account_id=p_account and batch.id::text=oc.result->'allocation'->>'batchId'
  and batch.state='complete' and batch.created_at<=oc.created_at;
 if not found or b.paid_receipt is null or jsonb_typeof(b.items) is distinct from 'array'
  or jsonb_typeof(b.results) is distinct from 'array' then return null;end if;
 if (select count(*) from jsonb_array_elements(b.items) x where x->>'screeningId'=p_screening::text)<>1
  or (select count(*) from jsonb_array_elements(b.results) x where x->>'screeningId'=p_screening::text)<>1 then return null;end if;
 select x into item from jsonb_array_elements(b.items) x where x->>'screeningId'=p_screening::text;
 select x->'result' into result from jsonb_array_elements(b.results) x where x->>'screeningId'=p_screening::text;
 if result is distinct from oc.result or item->'ids' is distinct from oc.result->'requestedPersonIds'
  or item->'snapshot'->>'propertyId' is distinct from oc.result->>'propertyId'
  or oc.operation_key is distinct from 'owners:'||p_account||':'||p_screening then return null;end if;
 -- Completed batch receipts/results are private and write-once through their
 -- existing service RPCs. Their original admission precedes the paid request.
 return b.created_at;
end $function$
